local ClampMaker = {}
local PRODUCTS = {
    iron_clamp = { name = "Železna štspanka", ironCost = 3, woodCost = 3, leatherCost = 1, time = 4, cost = 145, prestige = 3, happiness = 2, description = "Železna štspanka za prijemanje lesa." },
    bronze_clamp = { name = "Bronasta štspanka", bronzeCost = 3, ironCost = 1, woodCost = 3, leatherCost = 1, time = 6, cost = 350, prestige = 5, happiness = 3, description = "Bronasta štspanka za trdno prijemanje." },
    silver_clamp = { name = "Srebrna štspanka", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 1, time = 10, cost = 850, prestige = 10, happiness = 4, description = "Srebrna štspanka za plemiške mizarje." },
    gilded_clamp = { name = "Pozlačena štspanka", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 14, cost = 1820, prestige = 19, happiness = 5, description = "Pozlačena štspanka za dvorne mizarje." },
    jewel_set_clamp = { name = "Draguljasta štspanka", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 18, cost = 3950, prestige = 35, happiness = 7, description = "Draguljasta štspanka za kraljevske mizarje." },
    royal_sovereign_clamp = { name = "Kraljevski suverena štspanka", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 4, leatherCost = 1, time = 25, cost = 8500, prestige = 67, happiness = 13, description = "Suverena štspanka z biseri za krono." },
}
local BUILDINGS = {
    clamp_workshop = { name = "Štspančna delavnica", cost = { gold = 305, wood = 185, stone = 125, iron = 7 }, upkeep = 5, qualityBonus = 5 },
    clamp_house = { name = "Štspančna hiša", cost = { gold = 1135, wood = 370, stone = 260, silver = 6, iron = 7 }, upkeep = 24, qualityBonus = 18 },
    master_clamp_atelier = { name = "Mojstrski štspančni atelje", cost = { gold = 2880, wood = 430, stone = 500, silver = 33, gold = 6 }, upkeep = 68, qualityBonus = 30 },
    sovereign_clamp_palace = { name = "Suverena štspančna palača", cost = { gold = 12480, wood = 660, stone = 805, gold = 80, jewel = 18 }, upkeep = 246, qualityBonus = 55, prestigeBonus = 50 },
}
ClampMaker.ironStock = 14; ClampMaker.bronzeStock = 12; ClampMaker.woodStock = 16; ClampMaker.leatherStock = 10; ClampMaker.silverStock = 8; ClampMaker.goldStock = 6; ClampMaker.jewelStock = 4; ClampMaker.pearlStock = 4
ClampMaker.productStock = {}; ClampMaker.buildings = {}; ClampMaker.maker = nil; ClampMaker.activeMaking = {}; ClampMaker.totalProducts = 0; ClampMaker.dayTimer = 0
function ClampMaker.init() ClampMaker.ironStock=14; ClampMaker.bronzeStock=12; ClampMaker.woodStock=16; ClampMaker.leatherStock=10; ClampMaker.silverStock=8; ClampMaker.goldStock=6; ClampMaker.jewelStock=4; ClampMaker.pearlStock=4; ClampMaker.productStock={}; ClampMaker.buildings={}; ClampMaker.maker=nil; ClampMaker.activeMaking={}; ClampMaker.totalProducts=0; ClampMaker.dayTimer=0; print("[ClampMaker] Royal Clamp Maker System initialized (6 products, 4 buildings)") end
function ClampMaker.hireMaker(n,s) s=s or math.random(55,90); local c=565+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ClampMaker.maker={name=n or ("Štspankar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Štspankar najet: %s (spretnost: %d)",ClampMaker.maker.name,s),"success") end; return true end
function ClampMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ClampMaker.build(id) local ok,e=ClampMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ClampMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ClampMaker.getQualityBonus() local b=0; for _,bd in ipairs(ClampMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ClampMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ClampMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ClampMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ClampMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ClampMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ClampMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ClampMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ClampMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ClampMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ClampMaker.buildings==0 then return false,"Potrebna štspančna delavnica" end; if not ClampMaker.maker then return false,"Potreben štspankar" end; return true end
function ClampMaker.make(pt,qty) qty=qty or 1; local ok,e=ClampMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ClampMaker.ironStock=ClampMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ClampMaker.bronzeStock=ClampMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ClampMaker.woodStock=ClampMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ClampMaker.leatherStock=ClampMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ClampMaker.silverStock=ClampMaker.silverStock-d.silverCost*qty end; if d.goldCost then ClampMaker.goldStock=ClampMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ClampMaker.jewelStock=ClampMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ClampMaker.pearlStock=ClampMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ClampMaker.maker then t=math.max(1,t-math.floor(ClampMaker.maker.skill/13)) end; table.insert(ClampMaker.activeMaking,{id="clamp_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ClampMaker.completeMaking(m) local q=1.0+(ClampMaker.getQualityBonus()/100); if ClampMaker.maker then q=q+(ClampMaker.maker.skill/140) end; q=math.min(2.5,q); ClampMaker.productStock[m.productType]=(ClampMaker.productStock[m.productType] or 0)+m.quantity; ClampMaker.totalProducts=ClampMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ClampMaker.maker then ClampMaker.maker.itemsMade=ClampMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ClampMaker.maker.skill=math.min(100,ClampMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Štspanka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"clamp.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ClampMaker.update(dt) if not _G.state then return end; ClampMaker.dayTimer=ClampMaker.dayTimer+dt; if ClampMaker.dayTimer>=30 then ClampMaker.dayTimer=0; for i=#ClampMaker.activeMaking,1,-1 do local m=ClampMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ClampMaker.completeMaking(m); table.remove(ClampMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ClampMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ClampMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ClampMaker.getStats() return {ironStock=ClampMaker.ironStock,bronzeStock=ClampMaker.bronzeStock,woodStock=ClampMaker.woodStock,leatherStock=ClampMaker.leatherStock,silverStock=ClampMaker.silverStock,goldStock=ClampMaker.goldStock,jewelStock=ClampMaker.jewelStock,pearlStock=ClampMaker.pearlStock,productStock=ClampMaker.productStock,numBuildings=#ClampMaker.buildings,hasMaker=ClampMaker.maker~=nil,makerName=ClampMaker.maker and ClampMaker.maker.name or "—",makerSkill=ClampMaker.maker and ClampMaker.maker.skill or 0,activeMaking=#ClampMaker.activeMaking,totalProducts=ClampMaker.totalProducts} end
return ClampMaker
